const $ = selector => document.querySelector(selector);
const toast = message => { const node = $('#toast'); node.textContent = message; node.classList.add('show'); setTimeout(() => node.classList.remove('show'), 2600); };
document.addEventListener('click', event => { const button = event.target.closest('[data-report-download]'); if (!button) return; document.body.classList.add('report-printing'); window.print(); setTimeout(() => document.body.classList.remove('report-printing'), 800); });
const reportDownloadButton = label => `<button class="report-download-button" type="button" data-report-download>↓ ${label || 'Descargar PDF'}</button>`;
const ensureReportDownload = () => { const reportNav = document.querySelector('[data-finance-section="reports"].active, [data-domain-section="reports"].active'); const hero = document.querySelector('#workspace-content .hero'); if (reportNav && hero && !hero.querySelector('[data-report-download]')) { const actions = document.createElement('div'); actions.className = 'report-hero-actions'; actions.innerHTML = reportDownloadButton(); hero.appendChild(actions); } };
const reportObserver = new MutationObserver(ensureReportDownload);
if (document.body) reportObserver.observe(document.body, { childList: true, subtree: true });

async function api(path, options = {}) {
  const response = await fetch(`${path}`, { credentials: 'same-origin', ...options });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    const detail = Array.isArray(data.detail) ? data.detail.map(item => item.msg).join('. ') : (data.detail || 'No se pudo completar la operación');
    throw new Error(detail);
  }
  return data;
}

const formData = form => JSON.stringify(Object.fromEntries(new FormData(form)));
const showError = error => { $('#auth-error').textContent = error.message; };
let timesheetSimulation = null;

function showAuthPanel(panel) {
  $('#login-panel').hidden = panel !== 'login';
  $('#register-panel').hidden = panel !== 'register';
  $('#auth-error').textContent = '';
}

async function boot() {
  try { showApp(await api('/auth/me')); }
  catch { showAuthPanel('login'); }
}

function showApp(user) {
  $('#auth-view').hidden = true; $('#app-view').hidden = false; $('#user-name').textContent = `${user.username} · ${user.role}`;
  loadModules(user); loadOverview();
}

async function loadModules(user) {
  const { modules } = await api('/modules');
  $('#module-nav').innerHTML = modules.map(module => `<button class="nav-item ${module.key === 'overview' ? 'active' : ''}" data-module="${module.key}"><span>◈</span>${module.label}<span class="nav-status">${module.status === 'active' ? '●' : '·'}</span></button>`).join('');
  document.querySelectorAll('.nav-item').forEach(button => button.addEventListener('click', () => selectModule(button.dataset.module, modules)));
}

const overviewSections = [['presentation', 'Presentación'], ['glossary', 'Glosario'], ['data-model', 'Modelo de Datos'], ['areas', 'Áreas'], ['reports', 'Reportes']];
const overviewNav = active => `<nav class="finance-nav overview-nav">${overviewSections.map(([key, label]) => `<button class="finance-tab ${key === active ? 'active' : ''}" data-overview-section="${key}">${label}</button>`).join('')}</nav>`;
const overviewStorageKey = 'metalmecanica.overview.profile';
const overviewDefaultProfile = { description: 'Diseñamos y fabricamos soluciones metalmecánicas para proyectos industriales, infraestructura y mantenimiento.', mission: 'Resolver necesidades industriales con ingeniería, fabricación y montaje confiables.', vision: 'Ser un socio estratégico referente en soluciones metalmecánicas de alto valor en la región.', values: 'Seguridad · Calidad · Cumplimiento · Innovación · Trabajo en equipo', strengths: 'Experiencia técnica, capacidad de fabricación y trazabilidad digital.', opportunities: 'Nuevos sectores industriales, alianzas estratégicas y servicios de mantenimiento.', weaknesses: 'Dependencia de demanda por proyecto y necesidad de ampliar capacidad instalada.', threats: 'Variación de precios del acero, competencia y retrasos de abastecimiento.', news: [] };
const overviewProfile = () => { try { return { ...overviewDefaultProfile, ...(JSON.parse(localStorage.getItem(overviewStorageKey) || '{}')) }; } catch { return { ...overviewDefaultProfile }; } };
const saveOverviewProfile = profile => localStorage.setItem(overviewStorageKey, JSON.stringify(profile));

async function loadOverview(section = 'presentation') {
  const data = await api('/overview');
  if (section === 'presentation') return loadOverviewPresentation(data);
  if (section === 'glossary') return loadOverviewGlossary();
  if (section === 'data-model') return loadOverviewDataModel();
  const blankLabels = { glossary: ['Glosario', 'Define conceptos, siglas y reglas comunes de la operación.'], areas: ['Áreas', 'Organiza responsabilidades y relaciones entre equipos.'], reports: ['Reportes', 'Concentra reportes transversales de la compañía.'] };
  const [title, description] = blankLabels[section] || blankLabels.glossary;
  $('#page-title').textContent = 'Resumen'; $('#workspace-content').innerHTML = `${overviewNav(section)}<section class="hero"><div><p class="eyebrow">RESUMEN / ${title.toUpperCase()}</p><h2>${title}</h2><p>${description}</p></div><span class="hero-badge">● Espacio preparado</span></section><section class="module-card empty-overview-section"><div class="empty-state"><strong>Este submódulo está reservado para la siguiente iteración.</strong><span>La navegación ya está preparada para incorporar contenido sin alterar el resto del ERP.</span></div></section>`; bindOverviewNav();
}

const glossaryStorageKey = 'metalmecanica.overview.glossary';
const defaultGlossary = [
  ['Proyecto', 'Unidad de gestión que nace de una Orden de Servicio aprobada. Contiene alcance, fechas, piezas, responsables, BOM, planes y control de avance.'],
  ['Orden de Servicio (OS)', 'Documento comercial que formaliza el servicio contratado con el cliente. En Producción es el origen formal de uno o más proyectos y sus OTs.'],
  ['Orden de Trabajo (OT)', 'Instrucción de fabricación o ensamblaje derivada de un proyecto. Puede representar una pieza o el ensamblaje completo.'],
  ['Orden de Compra (OC)', 'Documento emitido a un proveedor para adquirir materiales o servicios solicitados por la operación.'],
  ['Crédito fiscal', 'IGV pagado en compras que puede compensarse contra el IGV generado por ventas, sujeto a la documentación y reglas tributarias aplicables.'],
  ['BOM', 'Bill of Materials o lista de materiales. Define piezas, elementos, materiales, cantidades y costos esperados de un proyecto.'],
  ['Cotización', 'Propuesta comercial que consolida alcance, materiales, mano de obra, tiempos, precio y condiciones antes de la aprobación del cliente.'],
  ['Kardex', 'Registro de entradas, salidas, consumos, devoluciones, mermas y retazos que explica el saldo de cada material en inventario.'],
  ['Retazo', 'Recorte de material que conserva utilidad y trazabilidad para ser reaprovechado en futuras órdenes de trabajo.'],
  ['Costo promedio', 'Valor unitario calculado a partir del costo promedio del material disponible y utilizado como referencia para el BOM.'],
  ['Hoja de ruta', 'Secuencia de procesos y estaciones de una OT, como corte, doblez, soldadura, pintado y ensamblaje.'],
  ['Tiempo muerto', 'Periodo o tarea sin avance productivo por falta de demanda, información, aprobación, material u otra dependencia.'],
].map(([term, meaning]) => ({ term, meaning, system: true }));
const glossaryItems = () => { try { const saved = JSON.parse(localStorage.getItem(glossaryStorageKey) || 'null'); return Array.isArray(saved) && saved.length ? saved : defaultGlossary; } catch { return defaultGlossary; } };
const saveGlossaryItems = items => localStorage.setItem(glossaryStorageKey, JSON.stringify(items));

function loadOverviewGlossary() {
  const items = glossaryItems(); const rows = items.map((item, index) => `<article class="glossary-item"><div><span class="pill ${item.system ? 'active' : 'planned'}">${item.system ? 'ERP' : 'Propio'}</span><h3>${htmlEscape(item.term)}</h3><p>${htmlEscape(item.meaning)}</p></div>${item.system ? '' : `<button class="link-button" type="button" data-delete-glossary="${index}">Eliminar</button>`}</article>`).join('');
  $('#page-title').textContent = 'Resumen'; $('#workspace-content').innerHTML = `${overviewNav('glossary')}<section class="hero"><div><p class="eyebrow">RESUMEN / GLOSARIO</p><h2>Lenguaje común de la operación</h2><p>Consulta los términos que conectan Ventas, Proyectos, Producción, Compras, Inventario, RR.HH. y Finanzas.</p></div><span class="hero-badge">● ${items.length} términos</span></section><section class="overview-glossary-layout"><section class="module-card"><div class="section-heading"><div><h3>Agregar término</h3><p class="muted">Registra conceptos propios de la compañía o del proyecto.</p></div></div><form id="glossary-form" class="compact-form"><input name="term" placeholder="Ej. Habilitado" required><textarea name="meaning" placeholder="Significado y uso dentro del ERP" required></textarea><button class="primary" type="submit">Agregar al glosario</button></form></section><section class="module-card"><div class="section-heading"><div><h3>Diccionario del ERP</h3><p class="muted">Los términos base se incluyen con el contexto actual del proyecto.</p></div></div><div class="glossary-list">${rows}</div></section></section>`;
  $('#glossary-form').addEventListener('submit', event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target)); const next = [...glossaryItems(), { term: values.term.trim(), meaning: values.meaning.trim(), system: false }]; saveGlossaryItems(next); toast('Término agregado al glosario'); loadOverviewGlossary(); });
  document.querySelectorAll('[data-delete-glossary]').forEach(button => button.addEventListener('click', () => { const next = glossaryItems(); next.splice(Number(button.dataset.deleteGlossary), 1); saveGlossaryItems(next); toast('Término eliminado'); loadOverviewGlossary(); })); bindOverviewNav();
}

function loadOverviewPresentation(data) {
  const profile = overviewProfile(); const newsRows = (profile.news || []).map((item, index) => `<div class="data-row"><span><strong>${htmlEscape(item.title)}</strong><small>${htmlEscape(item.date || 'Sin fecha')} · ${htmlEscape(item.text)}</small></span><button class="link-button" type="button" data-delete-news="${index}">Eliminar</button></div>`).join('');
  $('#page-title').textContent = 'Resumen'; $('#workspace-content').innerHTML = `${overviewNav('presentation')}<section class="hero"><div><p class="eyebrow">RESUMEN / PRESENTACIÓN</p><h2>Quiénes somos y hacia dónde vamos</h2><p>Una ficha ejecutiva para alinear la operación, la estrategia y las novedades de la compañía.</p></div><span class="hero-badge">● Perfil corporativo</span></section><section class="overview-profile-grid"><article class="module-card overview-intro-card"><span class="pill active">Identidad</span><h3>Presentación de la compañía</h3><p>${htmlEscape(profile.description)}</p><div class="overview-mvv"><div><small>Misión</small><strong>${htmlEscape(profile.mission)}</strong></div><div><small>Visión</small><strong>${htmlEscape(profile.vision)}</strong></div><div><small>Valores</small><strong>${htmlEscape(profile.values)}</strong></div></div></article><section class="module-card"><div class="section-heading"><div><h3>Editar perfil corporativo</h3><p class="muted">Los cambios se guardan en este espacio de trabajo.</p></div></div><form id="overview-profile-form" class="compact-form"><textarea name="description" placeholder="Descripción de la compañía" required>${htmlEscape(profile.description)}</textarea><textarea name="mission" placeholder="Misión" required>${htmlEscape(profile.mission)}</textarea><textarea name="vision" placeholder="Visión" required>${htmlEscape(profile.vision)}</textarea><input name="values" value="${htmlEscape(profile.values)}" placeholder="Valores separados por ·" required><button class="primary" type="submit">Guardar presentación</button></form></section></section><section class="report-section-grid"><article class="module-card report-card"><div class="section-heading"><div><h3>Análisis FODA</h3><p class="muted">Lectura estratégica para orientar decisiones.</p></div></div><form id="overview-swot-form" class="customer-form"><label>Fortalezas<textarea name="strengths">${htmlEscape(profile.strengths)}</textarea></label><label>Oportunidades<textarea name="opportunities">${htmlEscape(profile.opportunities)}</textarea></label><label>Debilidades<textarea name="weaknesses">${htmlEscape(profile.weaknesses)}</textarea></label><label>Amenazas<textarea name="threats">${htmlEscape(profile.threats)}</textarea></label><button class="primary" type="submit">Guardar FODA</button></form></article><article class="module-card report-card"><div class="section-heading"><div><h3>Noticias y novedades</h3><p class="muted">Registra hitos relevantes de la compañía.</p></div></div><form id="overview-news-form" class="compact-form"><input name="title" placeholder="Título de la noticia" required><input name="date" type="date"><textarea name="text" placeholder="Resumen de la novedad" required></textarea><button class="primary" type="submit">Agregar noticia</button></form><div class="data-list">${newsRows || '<p class="muted">Aún no hay noticias registradas.</p>'}</div></article></section>`;
  $('#overview-profile-form').addEventListener('submit', event => { event.preventDefault(); saveOverviewProfile({ ...overviewProfile(), ...Object.fromEntries(new FormData(event.target)) }); toast('Presentación actualizada'); loadOverviewPresentation(data); });
  $('#overview-swot-form').addEventListener('submit', event => { event.preventDefault(); saveOverviewProfile({ ...overviewProfile(), ...Object.fromEntries(new FormData(event.target)) }); toast('Análisis FODA actualizado'); loadOverviewPresentation(data); });
  $('#overview-news-form').addEventListener('submit', event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target)); const next = overviewProfile(); next.news = [...(next.news || []), values]; saveOverviewProfile(next); toast('Noticia agregada'); loadOverviewPresentation(data); });
  document.querySelectorAll('[data-delete-news]').forEach(button => button.addEventListener('click', () => { const next = overviewProfile(); next.news.splice(Number(button.dataset.deleteNews), 1); saveOverviewProfile(next); loadOverviewPresentation(data); })); bindOverviewNav();
}

function loadOverviewDataModel() {
  $('#page-title').textContent = 'Resumen'; $('#workspace-content').innerHTML = `${overviewNav('data-model')}<section class="hero"><div><p class="eyebrow">RESUMEN / MODELO DE DATOS</p><h2>Mapa de trazabilidad del negocio</h2><p>Después de la documentación y las aprobaciones, todo converge en Ejecución. Sus áreas se relacionan sobre el mismo proyecto, materiales, personas y dinero.</p></div><span class="hero-badge">● Vista conceptual</span></section><section class="module-card data-model-card"><div class="section-heading"><div><h3>Qué origina qué</h3><p class="muted">Haz clic en un nodo para ver su relación con el resto del flujo.</p></div><span class="pill active">Cliente → OS → Proyecto → Ejecución</span></div><div class="concept-map"><button class="concept-node root" data-model-node="customer"><strong>Cliente</strong><small>Necesidad / solicitud</small></button><span class="concept-arrow">↓</span><button class="concept-node" data-model-node="visit"><strong>Solicitud de visita</strong><small>Levantamiento técnico</small></button><span class="concept-arrow">↓</span><button class="concept-node" data-model-node="quote-request"><strong>Solicita cotización</strong><small>Requisitos y alcance</small></button><span class="concept-arrow">↓</span><button class="concept-node" data-model-node="quote"><strong>Cotización</strong><small>Costos, precio y condiciones</small></button><span class="concept-arrow">↓</span><button class="concept-node" data-model-node="approval"><strong>Aprobación comercial</strong><small>Si continúa · No: revisar y reintentar</small></button><span class="concept-arrow">↓</span><button class="concept-node key-node" data-model-node="service-order"><strong>Orden de Servicio</strong><small>Origen formal del Proyecto</small></button><span class="concept-arrow">↓</span><button class="concept-node key-node" data-model-node="project"><strong>Proyecto</strong><small>Fechas, alcance, piezas y responsables</small></button><div class="concept-connectors">↙　　　　　　　　　　　　　　　　　↘</div><div class="concept-branches project-types"><button class="concept-node project-type" data-model-node="metal-structures"><strong>Estructuras metálicas</strong><small>Fabricación y montaje de estructuras</small></button><button class="concept-node project-type" data-model-node="metalwork"><strong>Carpintería metálica</strong><small>Puertas, barandas, soportes y acabados</small></button></div><div class="concept-arrow">↓</div><button class="concept-node" data-model-node="technical-docs"><strong>Documentación y aprobaciones</strong><small>Planos · especificaciones · calidad · SSOMA · oficina técnica</small></button><div class="concept-arrow">↓</div><button class="concept-node execution-node" data-model-node="execution"><strong>Ejecución</strong><small>Coordina el proyecto de punta a punta</small></button><div class="concept-connectors">↙　↘　↓　↙　↘　↓</div><div class="concept-branches execution-branches"><button class="concept-node" data-model-node="production"><strong>Producción</strong><small>BOM · plan · OT por pieza/ensamblaje · tiempos</small></button><button class="concept-node" data-model-node="purchases"><strong>Compras</strong><small>Items 001/002 · cotizaciones · OC</small></button><button class="concept-node" data-model-node="hr"><strong>RR.HH.</strong><small>Asignaciones · costo · horas reales</small></button><button class="concept-node" data-model-node="inventory"><strong>Inventario</strong><small>Acero · pintura · EPP · consumo · retazos</small></button><button class="concept-node" data-model-node="finance"><strong>Finanzas</strong><small>Ventas · compras · bancos · flujo de caja</small></button><button class="concept-node" data-model-node="delivery"><strong>Entrega</strong><small>Conformidad · cierre · rentabilidad</small></button></div><section class="execution-trace"><div class="section-heading"><div><h3>Ejemplo de trazabilidad: PRJ-001</h3><p class="muted">Un mismo código conecta las áreas; los registros no viven aislados.</p></div><span class="pill active">Vista integrada</span></div><div class="trace-grid"><div><small>Producción</small><strong>5 OT de piezas + 1 OT de ensamblaje</strong><span>OT-001 … OT-006</span></div><div><small>Compras</small><strong>Items 001 y 002</strong><span>Se convierten en entradas o tránsito</span></div><div><small>Inventario</small><strong>Acero, pintura y EPP</strong><span>El BOM reserva, consume y registra retazos</span></div><div><small>RR.HH.</small><strong>Horas y costo laboral</strong><span>Asignaciones y tiempos reales del proyecto</span></div><div><small>Finanzas</small><strong>Ventas + compras + otros gastos</strong><span>Impactan caja, costo y rentabilidad</span></div><div><small>Entrega</small><strong>Conformidad y cierre</strong><span>Consolida el resultado del proyecto</span></div></div></section><p id="model-node-detail" class="model-node-detail">Selecciona un nodo para ver su relación con el resto del flujo.</p></div></section>`;
  const details = { customer: 'El cliente inicia la relación con una necesidad, requerimiento o solicitud de servicio.', visit: 'La solicitud de visita origina el levantamiento técnico: medidas, condiciones, restricciones y evidencias.', 'quote-request': 'El levantamiento y los requisitos del cliente originan la solicitud de cotización.', quote: 'La cotización consolida alcance, materiales, mano de obra, tiempos, precio y condiciones comerciales.', approval: 'La aprobación comercial decide si se continúa con la Orden de Servicio o se devuelve para revisión y reintento.', 'service-order': 'La Orden de Servicio aprobada es el origen formal del proyecto y mantiene la relación con Ventas y el cliente.', project: 'Cada OS puede originar un proyecto con fechas, responsables, piezas, documentación y control de avance.', 'metal-structures': 'Tipo de proyecto: Estructuras metálicas. Se orienta a fabricación y montaje de estructuras, con BOM, piezas y ensamblaje.', metalwork: 'Tipo de proyecto: Carpintería metálica. Se orienta a puertas, barandas, soportes, cerramientos y acabados metálicos.', 'technical-docs': 'El proyecto requiere documentación, planos y aprobaciones de Oficina Técnica, Calidad, Administración, SSOMA, Residente y Planeamiento.', execution: 'Ejecución es el nodo coordinador: todas las áreas operan sobre el mismo proyecto y sus transacciones alimentan el costo y el avance.', production: 'Producción recibe el proyecto y trabaja con BOM de materiales, plan de producción, OTs por pieza o ensamblaje, rutas y tiempos.', purchases: 'Compras atiende los items derivados del BOM y del proyecto; sus cotizaciones y órdenes generan tránsito y costo.', hr: 'RR.HH. asigna personal al proyecto y permite controlar horas estimadas, costo laboral y horas reales.', inventory: 'Compras alimenta el inventario; Producción consume perfiles, planchas, pintura y EPP, y registra mermas o retazos trazables.', finance: 'Finanzas integra ventas, compras, RR.HH., otros gastos y bancos para calcular caja, costo y rentabilidad.', delivery: 'La operación culmina con entrega, conformidad, cierre del proyecto y análisis de rentabilidad.' };
  const modelDestinations = { customer: ['selling', 'customers'], visit: ['selling', 'technical-visits'], 'quote-request': ['selling', 'quotations'], quote: ['selling', 'quotations'], approval: ['selling', 'quotations'], 'service-order': ['selling', 'service-orders'], project: ['projects', 'projects'], 'metal-structures': ['projects', 'projects'], metalwork: ['projects', 'projects'], 'technical-docs': ['projects', 'tasks'], execution: ['production', 'dashboard'], production: ['production', 'reports'], purchases: ['purchases', 'reports'], hr: ['hr', 'dashboard'], inventory: ['inventory', 'dashboard'], finance: ['accounts', 'dashboard'], delivery: ['projects', 'dashboard'] };
  const navigateFromModel = node => { const destination = modelDestinations[node]; if (!destination) return; const [module, section] = destination; if (module === 'selling') return loadSales(section); if (module === 'accounts') return loadFinance(section); if (module === 'hr') return loadHR(section); return loadDomain(module, section); };
  document.querySelectorAll('[data-model-node]').forEach(button => button.addEventListener('click', () => { const node = button.dataset.modelNode; document.querySelectorAll('[data-model-node]').forEach(item => item.classList.toggle('selected', item === button)); $('#model-node-detail').textContent = `${details[node]} · Abriendo sección relacionada…`; navigateFromModel(node); })); bindOverviewNav();
}

function bindOverviewNav() { document.querySelectorAll('[data-overview-section]').forEach(button => button.addEventListener('click', () => loadOverview(button.dataset.overviewSection))); }

const moduleCard = module => `<article class="module-card ${module.status}"><span class="pill ${module.status}">${module.status === 'active' ? 'Activo' : 'Próximamente'}</span><h3>${module.label}</h3><p>${module.description}</p></article>`;

async function selectModule(key, modules) {
  document.querySelectorAll('.nav-item').forEach(item => item.classList.toggle('active', item.dataset.module === key));
  if (key === 'overview') return loadOverview();
  if (key === 'accounts') return loadFinance();
  if (key === 'accounting') return loadFinance('accounts');
  if (key === 'selling') return loadSales();
  if (['purchases', 'inventory', 'production', 'projects'].includes(key)) return loadDomain(key);
  if (key === 'hr') return loadHR();
  if (key === 'settings') return loadSettings();
  const module = modules.find(item => item.key === key); $('#page-title').textContent = module.label;
  $('#workspace-content').innerHTML = `<section class="hero"><div><p class="eyebrow">MÓDULO ${module.status === 'active' ? 'ACTIVO' : 'EN DISEÑO'}</p><h2>${module.label}</h2><p>${module.description}</p></div><span class="hero-badge">${module.status === 'active' ? 'Disponible' : 'Planificado'}</span></section><h2 class="section-title">Siguiente iteración</h2><article class="module-card"><h3>Espacio preparado</h3><p>Este apartado ya tiene navegación, permisos y una API propia. Aquí crecerán los casos de uso del módulo.</p></article>`;
}

