async function loadFinanceReportsV2(summary, companyId = null) {
  const selectedCompany = companyId || summary.company_list[0]?.id;
  const data = selectedCompany ? await api(`/accounts/finance-overview?company_id=${selectedCompany}`) : { kpis: {}, monthly: [], recent: [] };
  const k = data.kpis || {};
  const monthly = data.monthly || [];
  const money = value => `S/ ${Number(value || 0).toLocaleString('es-PE', { minimumFractionDigits: 2 })}`;
  const percent = value => `${Number(value || 0).toLocaleString('es-PE', { maximumFractionDigits: 1 })}%`;
  const ratio = value => `${Number(value || 0).toLocaleString('es-PE', { maximumFractionDigits: 2 })}x`;
  const ingresos = Number(k.cash_in || 0);
  const egresos = Number(k.cash_out || 0);
  const neto = Number(k.net_cash || 0);
  const caja = Number(k.cash_balance || 0);
  const cobrar = Number(k.receivable || 0);
  const pagar = Number(k.payable || 0);
  const periods = Math.max(monthly.length, 1);
  const liquidez = (caja + cobrar) / Math.max(pagar, 1);
  const endeudamiento = (pagar / Math.max(caja + cobrar, 1)) * 100;
  const margenCaja = (neto / Math.max(ingresos, 1)) * 100;
  const coberturaEgresos = caja / Math.max(egresos, 1);
  const capitalTrabajo = caja + cobrar - pagar;
  const ingresosAnualizados = (ingresos / periods) * 12;
  const flujoAnualizado = (neto / periods) * 12;
  const max = Math.max(1, ...monthly.flatMap(row => [Number(row.inflows || 0), Number(row.outflows || 0)]));
  const metrics = [
    ['teal', 'Ingresos cobrados', money(ingresos), 'Entradas registradas'],
    ['red', 'Egresos pagados', money(egresos), 'Salidas registradas'],
    ['blue', 'Flujo neto', money(neto), 'Ingresos menos egresos'],
    ['amber', 'Saldo de caja', money(caja), 'Caja inicial + flujo neto'],
    ['purple', 'Liquidez inmediata', ratio(liquidez), '(Caja + cobrar) / pagar'],
    ['blue', 'Endeudamiento operativo', percent(endeudamiento), 'Por pagar / recursos líquidos'],
    ['teal', 'Margen de caja', percent(margenCaja), 'Flujo neto / ingresos'],
    ['amber', 'Cobertura de egresos', ratio(coberturaEgresos), 'Meses equivalentes de caja'],
    ['purple', 'Capital de trabajo', money(capitalTrabajo), 'Caja + cobrar − pagar'],
    ['blue', 'Ingresos anualizados', money(ingresosAnualizados), `Run-rate sobre ${periods} periodo${periods === 1 ? '' : 's'}`],
  ];
  const metricCards = metrics.map(([tone, label, value, note]) => `<article class="metric-card ${tone}"><small>${label}</small><strong>${value}</strong><span class="kpi-note">${note}</span></article>`).join('');
  const monthlyRows = monthly.map(row => `<tr><td><strong>${row.month}</strong></td><td class="amount-in">${money(row.inflows)}</td><td class="amount-out">${money(row.outflows)}</td><td><strong>${money(Number(row.inflows || 0) - Number(row.outflows || 0))}</strong></td></tr>`).join('');
  const recentRows = (data.recent || []).map(row => `<div class="data-row"><span><strong>${htmlEscape(row.description)}</strong><small>${row.movement_date} · ${htmlEscape(row.category)} · ${row.status}</small></span><strong class="${row.direction === 'inflow' ? 'amount-in' : 'amount-out'}">${row.direction === 'inflow' ? '+' : '-'} ${money(row.amount)}</strong></div>`).join('');
  const valuationRows = `<div><span>Ingresos anualizados</span><strong>${money(ingresosAnualizados)}</strong></div><div><span>Flujo neto anualizado</span><strong>${money(flujoAnualizado)}</strong></div><div><span>Margen de caja</span><strong>${percent(margenCaja)}</strong></div><div><span>Capital de trabajo</span><strong>${money(capitalTrabajo)}</strong></div>`;
  $('#page-title').textContent = 'Finanzas';
  $('#workspace-content').innerHTML = `${financeNav('reports')}<section class="hero"><div><p class="eyebrow">FINANZAS / REPORTES</p><h2>KPIs financieros</h2><p>Lectura integral de caja, compromisos y capacidad de generación de efectivo para una empresa de servicios.</p></div><span class="hero-badge">● Datos operativos</span></section><section class="finance-analysis-note"><strong>Nota metodológica</strong><span>Los ratios se calculan con caja, cuentas por cobrar y cuentas por pagar disponibles en el ERP. Son indicadores gerenciales de referencia; para ratios contables formales aún se requiere completar activo, pasivo, patrimonio, deuda financiera y resultados devengados.</span></section><div class="card-grid finance-kpi-grid">${metricCards}</div><section class="report-section-grid"><article class="module-card report-card"><div class="section-heading"><div><h3>Base para valoración</h3><p class="muted">Constancia numérica para futuras valoraciones por flujo o múltiplos.</p></div><span class="pill planned">Referencia</span></div><div class="finance-valuation-grid">${valuationRows}</div><p class="finance-footnote">El run-rate anualiza los periodos disponibles. No representa todavía EBITDA ni valor de compañía; sirve como base consistente para incorporar luego un múltiplo sectorial o un modelo DCF.</p></article><article class="module-card report-card"><div class="section-heading"><div><h3>Aplicabilidad de KPIs</h3><p class="muted">Priorización para una empresa de servicios metalmecánicos.</p></div></div><div class="finance-applicability"><div><span class="pill active">Aplican hoy</span><p>Ingresos, egresos, flujo neto, caja, liquidez, cuentas por cobrar/pagar, margen de caja y capital de trabajo.</p></div><div><span class="pill planned">Completar después</span><p>Margen bruto, EBITDA, deuda total, ROA, ROE y valoración formal: dependen de contabilidad devengada y balance completo.</p></div></div></article></section><section class="report-section-grid"><article class="module-card report-card"><div class="section-heading"><div><h3>Ingresos vs. egresos mensuales</h3><p class="muted">Verde: entradas · Rojo: salidas · debajo, flujo neto.</p></div></div><div class="finance-report-chart">${monthly.map(row => `<div class="finance-report-bar"><div class="bar-pair"><i class="in" style="height:${Math.max(4, Number(row.inflows || 0) / max * 150)}px"></i><i class="out" style="height:${Math.max(4, Number(row.outflows || 0) / max * 150)}px"></i></div><strong>${row.month}</strong><small>${money(Number(row.inflows || 0) - Number(row.outflows || 0))}</small></div>`).join('') || '<p class="muted">Sin datos mensuales.</p>'}</div></article><article class="module-card report-card"><div class="section-heading"><div><h3>Lectura rápida</h3><p class="muted">Indicadores que explican la posición actual.</p></div></div><div class="finance-insight-list"><div><span>Liquidez inmediata</span><strong>${ratio(liquidez)}</strong></div><div><span>Endeudamiento operativo</span><strong>${percent(endeudamiento)}</strong></div><div><span>Cobertura de egresos</span><strong>${ratio(coberturaEgresos)}</strong></div><div><span>Flujo neto anualizado</span><strong>${money(flujoAnualizado)}</strong></div></div></article></section><section class="module-card finance-table-card"><div class="section-heading"><div><h3>Detalle mensual</h3><p class="muted">Valores consolidados para análisis y trazabilidad.</p></div></div><div class="directory-table-wrap"><table class="directory-table"><thead><tr><th>Periodo</th><th>Ingresos</th><th>Egresos</th><th>Neto</th></tr></thead><tbody>${monthlyRows || '<tr><td colspan="4">No hay periodos registrados.</td></tr>'}</tbody></table></div></section><section class="module-card"><div class="section-heading"><h3>Movimientos recientes</h3><span class="pill active">${k.movement_count || 0}</span></div><div class="data-list">${recentRows || '<p class="muted">No hay movimientos recientes.</p>'}</div></section>`;
  bindFinanceNav();
}

async function loadFinanceBanks(summary, companyId = null) {
  const selectedCompany = companyId || summary.company_list[0]?.id;
  const [banks, accounts] = await Promise.all([api('/accounts/banks'), selectedCompany ? api(`/accounts/cash-accounts?company_id=${selectedCompany}`) : Promise.resolve({ accounts: [] })]);
  const bankOptions = banks.banks.map(bank => `<option value="${bank.id}">${htmlEscape(bank.name)} · ${htmlEscape(bank.country)}</option>`).join('');
  const bankAccounts = accounts.accounts.filter(account => account.account_type === 'bank');
  const accountRows = bankAccounts.map(account => `<tr><td><strong>${htmlEscape(account.code)}</strong><small>${htmlEscape(account.name)}</small></td><td>${htmlEscape(account.institution_name || account.bank_name || 'Sin banco')}</td><td>${htmlEscape(account.account_number_masked || 'Número no registrado')}</td><td>Cuenta bancaria</td><td class="numeric"><strong>S/ ${Number(account.opening_balance || 0).toLocaleString('es-PE', {minimumFractionDigits: 2})}</strong></td></tr>`).join('');
  const bankRows = banks.banks.map(bank => `<tr><td><strong>${htmlEscape(bank.name)}</strong><small>${htmlEscape(bank.country)} · ${bank.account_count} cuenta${Number(bank.account_count) === 1 ? '' : 's'}</small></td><td><form class="bank-website-form" data-bank-id="${bank.id}"><input name="website" type="url" value="${htmlEscape(bank.website || '')}" placeholder="https://sitio-oficial.pe"><button class="link-button" type="submit">Guardar</button></form></td></tr>`).join('');
  $('#page-title').textContent = 'Finanzas'; $('#workspace-content').innerHTML = `${financeNav('banks')}<section class="hero"><div><p class="eyebrow">FINANZAS / TESORERÍA</p><h2>Bancos y cuentas</h2><p>Directorio operativo de cuentas bancarias y referencia editable del sitio oficial de cada banco.</p></div><button class="primary" id="new-cash-account" type="button">+ Agregar cuenta</button></section><section class="module-card finance-directory-card"><div class="section-heading"><div><h3>Cuentas bancarias</h3><p class="muted">${bankAccounts.length} cuenta${bankAccounts.length === 1 ? '' : 's'} registrada${bankAccounts.length === 1 ? '' : 's'} en la compañía.</p></div><span class="pill active">Solo cuentas bancarias</span></div><div class="directory-table-wrap"><table class="directory-table"><thead><tr><th>Código / cuenta</th><th>Banco</th><th>Número visible</th><th>Tipo</th><th class="numeric">Saldo inicial</th></tr></thead><tbody>${accountRows || '<tr><td colspan="5">Aún no hay cuentas bancarias registradas.</td></tr>'}</tbody></table></div></section><section class="module-card finance-directory-card"><div class="section-heading"><div><h3>Directorio de bancos</h3><p class="muted">Solo se edita el sitio web oficial desde este directorio.</p></div><span class="pill planned">${banks.banks.length} bancos</span></div><div class="directory-table-wrap"><table class="directory-table"><thead><tr><th>Banco</th><th>Sitio web oficial</th></tr></thead><tbody>${bankRows || '<tr><td colspan="2">No hay bancos registrados.</td></tr>'}</tbody></table></div></section><div class="modal-backdrop" id="cash-account-modal" hidden><section class="customer-modal" role="dialog" aria-modal="true" aria-labelledby="cash-account-title"><div class="customer-modal-header"><div><p class="eyebrow">FINANZAS / TESORERÍA</p><h3 id="cash-account-title">Agregar cuenta bancaria</h3><p class="muted">Registra una cuenta operativa vinculada a un banco.</p></div><button class="modal-close" id="cash-account-cancel" type="button">×</button></div><form id="cash-account-form" class="customer-form"><div class="customer-grid"><label>Banco<select name="bank_id" required><option value="">Selecciona un banco</option>${bankOptions}</select></label><label>Código interno<input name="code" placeholder="BCP-PEN" required></label><label>Nombre de cuenta<input name="name" placeholder="Cuenta corriente principal" required></label><label>Número visible<input name="account_number_masked" placeholder="**** 4821"></label><label>Tipo<select name="account_type"><option value="bank">Cuenta bancaria</option></select></label><label>Saldo inicial<input name="opening_balance" type="number" min="0" step="0.01" value="0"></label></div><div class="company-form-footer"><button class="primary" type="submit">Guardar cuenta</button><button class="link-button" id="cash-account-reset" type="button">Cancelar</button></div></form></section></div>`;
  const modal = $('#cash-account-modal'); const close = () => { modal.hidden = true; document.body.classList.remove('modal-open'); }; $('#new-cash-account').addEventListener('click', () => { modal.hidden = false; document.body.classList.add('modal-open'); }); $('#cash-account-cancel').addEventListener('click', close); $('#cash-account-reset').addEventListener('click', close); modal.addEventListener('click', event => { if (event.target === modal) close(); }); $('#cash-account-form').addEventListener('submit', async event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target)); try { await api('/accounts/cash-accounts', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ company_id: Number(selectedCompany), ...values, bank_id: Number(values.bank_id), opening_balance: Number(values.opening_balance || 0) }) }); close(); toast('Cuenta bancaria registrada'); loadFinance('banks', selectedCompany); } catch (error) { toast(error.message); } });
  document.querySelectorAll('.bank-website-form').forEach(form => form.addEventListener('submit', async event => { event.preventDefault(); const bank = banks.banks.find(item => String(item.id) === form.dataset.bankId); const values = Object.fromEntries(new FormData(form)); if (!bank) return; try { await api(`/accounts/banks/${bank.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: bank.name, country: bank.country, website: values.website || null, api_provider: bank.api_provider || null, integration_status: bank.integration_status, notes: bank.notes || null }) }); toast('Sitio web actualizado'); loadFinance('banks', selectedCompany); } catch (error) { toast(error.message); } })); bindFinanceNav();
}

