  const rows = invoices.map(row => `<tr><td><strong>${htmlEscape(row.document_code)}</strong></td><td>${row.issue_date}</td><td>${htmlEscape(row.customer_name)}</td><td>${htmlEscape(row.order_code || 'Sin orden')}</td><td><span class="pill ${row.status === 'issued' ? 'active' : 'planned'}">${row.status === 'issued' ? 'Emitida' : 'Borrador'}</span></td><td class="numeric">S/ ${Number(row.total_amount || 0).toLocaleString('es-PE', {minimumFractionDigits: 2})}</td></tr>`).join('');
