  const customerOptions = customers.map(customer => `<option value="${customer.id}">${htmlEscape(customer.name)}</option>`).join('');
  const orderOptions = orders.map(order => `<option value="${order.id}">${htmlEscape(order.order_code)}</option>`).join('');
  const statusLabels = { planned: 'Programada', completed: 'Realizada', cancelled: 'Cancelada' };
