  $('#workspace-content').innerHTML = `${domainNav(definition, 'tasks')}<section class="hero"><div><p class="eyebrow">MÓDULO PROYECTOS / TAREAS</p><h2>Tareas</h2><p>Controla tareas productivas y tiempos muertos, incluyendo la documentación de cada área.</p></div><button class="primary customer-new-button" id="new-task" type="button">+ Nueva tarea</button></section><section class="module-card customer-directory"><div class="section-heading"><div><h3>Directorio</h3><p class="muted"><span id="task-result-count">${tasks.length}</span> de ${tasks.length} tarea${tasks.length === 1 ? '' : 's'}.</p></div></div><div class="directory-filters" aria-label="Filtros de tareas"><label>Buscar<input id="task-filter-search" type="search" placeholder="Código, nombre o proyecto"></label><label>Proyecto<select id="task-filter-project"><option value="">Todos</option>${projects.map(project => `<option value="${project.id}">${htmlEscape(project.project_code)}</option>`).join('')}</select></label><label>Tipo<select id="task-filter-type"><option value="">Todos</option><option value="documentation">Documentación</option><option value="general">General</option><option value="engineering">Ingeniería</option><option value="production">Producción</option><option value="quality">Calidad</option><option value="administration">Administración</option></select></label><label>Estado<select id="task-filter-status"><option value="">Todos</option><option value="planned">Planificada</option><option value="in_progress">En ejecución</option><option value="blocked">Bloqueada</option><option value="completed">Completada</option><option value="cancelled">Cancelada</option></select></label><label>Clasificación<select id="task-filter-dead"><option value="">Todas</option><option value="yes">Tiempo muerto</option><option value="no">Productiva</option></select></label><button class="link-button filter-clear" id="task-filter-clear" type="button">Limpiar filtros</button></div>${taskRows ? `<div class="directory-table-wrap"><table class="directory-table"><thead><tr><th>Código</th><th>Tarea</th><th>Proyecto</th><th>Tipo</th><th>Planificación</th><th>Ejecución</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${taskRows}</tbody></table></div>` : '<div class="empty-state">Aún no hay tareas registradas.</div>'}</section><div class="modal-backdrop" id="task-modal" hidden><section class="customer-modal task-modal" role="dialog" aria-modal="true" aria-labelledby="task-form-title"><div class="customer-modal-header"><div><p class="eyebrow">CONTROL DEL PROYECTO</p><h3 id="task-form-title">Nueva tarea</h3><p class="muted">Las tareas documentales se consideran tiempo muerto hasta su aprobación.</p></div><button class="modal-close" id="task-cancel" type="button" aria-label="Cerrar">×</button></div><form id="task-form" class="customer-form"><input type="hidden" name="task_id"><label>Proyecto *<select name="project_id" required><option value="">Selecciona un proyecto</option>${projectOptions}</select></label><div class="customer-grid"><label>Código de tarea *<input name="task_code" required placeholder="T-001"></label><label>Nombre *<input name="name" required placeholder="Revisión de planos"></label><label>Tipo<select name="task_type"><option value="general">General</option><option value="documentation">Documentación</option><option value="engineering">Ingeniería</option><option value="production">Producción</option><option value="quality">Calidad</option><option value="administration">Administración</option></select></label><label>Área<input name="area_key" placeholder="production"></label><label>Inicio planificado<input name="planned_start" type="date"></label><label>Fin planificado<input name="planned_end" type="date"></label><label>Inicio real<input name="actual_start" type="date"></label><label>Fin real<input name="actual_end" type="date"></label><label>Estado<select name="status"><option value="planned">Planificada</option><option value="in_progress">En ejecución</option><option value="blocked">Bloqueada</option><option value="completed">Completada</option><option value="cancelled">Cancelada</option></select></label></div><label class="checkbox-field"><input name="is_dead_time" type="checkbox"> Registrar como tiempo muerto</label><label>Observaciones<textarea name="observations" placeholder="Dependencias, bloqueos o notas"></textarea></label><div class="company-form-footer"><button class="primary" type="submit">Guardar tarea</button><button class="link-button" id="task-reset" type="button" hidden>Cancelar edición</button></div></form></section></div>`;
  const form = $('#task-form'); const modal = $('#task-modal');
  const resetForm = () => { form.reset(); form.elements.task_id.value = ''; form.elements.status.value = 'planned'; $('#task-form-title').textContent = 'Nueva tarea'; $('#task-reset').hidden = true; };
  const closeModal = () => { modal.hidden = true; document.body.classList.remove('modal-open'); };
  const openModal = () => { modal.hidden = false; document.body.classList.add('modal-open'); form.elements.project_id.focus(); };
  $('#new-task').addEventListener('click', () => { resetForm(); openModal(); });
  $('#task-cancel').addEventListener('click', () => { closeModal(); resetForm(); });
  $('#task-reset').addEventListener('click', () => { closeModal(); resetForm(); });
  modal.addEventListener('click', event => { if (event.target === modal) { closeModal(); resetForm(); } });
  const filterTasks = () => { const search = $('#task-filter-search').value.trim().toLowerCase(); const project = $('#task-filter-project').value; const type = $('#task-filter-type').value; const status = $('#task-filter-status').value; const dead = $('#task-filter-dead').value; let visible = 0; document.querySelectorAll('[data-filter-row]').forEach(row => { const matches = (!search || row.dataset.search.includes(search)) && (!project || row.dataset.project === project) && (!type || row.dataset.type === type) && (!status || row.dataset.status === status) && (!dead || row.dataset.dead === dead); row.hidden = !matches; if (matches) visible += 1; }); $('#task-result-count').textContent = visible; };
