  $('#task-filter-clear').addEventListener('click', () => { ['task-filter-search', 'task-filter-project', 'task-filter-type', 'task-filter-status', 'task-filter-dead'].forEach(id => { const node = $(`#${id}`); node.value = ''; }); filterTasks(); });
  form.addEventListener('submit', async event => { event.preventDefault(); const values = Object.fromEntries(new FormData(form)); const payload = { project_id: Number(values.project_id), task_code: values.task_code, name: values.name, task_type: values.task_type, area_key: values.area_key || null, planned_start: values.planned_start || null, planned_end: values.planned_end || null, actual_start: values.actual_start || null, actual_end: values.actual_end || null, status: values.status, is_dead_time: form.elements.is_dead_time.checked, observations: values.observations || null }; const taskId = values.task_id; try { await api(taskId ? `/projects/tasks/${taskId}` : '/projects/tasks', { method: taskId ? 'PATCH' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); closeModal(); toast(taskId ? 'Tarea actualizada' : 'Tarea registrada'); loadTasks(); } catch (error) { toast(error.message); } });
  document.querySelectorAll('[data-edit-task]').forEach(button => button.addEventListener('click', () => { const task = tasks.find(item => String(item.id) === button.dataset.editTask); if (!task) return; form.elements.task_id.value = task.id; form.elements.project_id.value = task.project_id; form.elements.task_code.value = task.task_code; form.elements.name.value = task.name; form.elements.task_type.value = task.task_type; form.elements.area_key.value = task.area_key || ''; form.elements.planned_start.value = task.planned_start || ''; form.elements.planned_end.value = task.planned_end || ''; form.elements.actual_start.value = task.actual_start || ''; form.elements.actual_end.value = task.actual_end || ''; form.elements.status.value = task.status; form.elements.is_dead_time.checked = Boolean(task.is_dead_time); form.elements.observations.value = task.observations || ''; $('#task-form-title').textContent = 'Editar tarea'; $('#task-reset').hidden = false; openModal(); }));
  resetForm();
  document.querySelectorAll('[data-domain-section]').forEach(button => button.addEventListener('click', () => loadDomain('projects', button.dataset.domainSection)));
