  const itemRows = items.map(item => `<tr data-purchase-item-row data-search="${htmlEscape(`${item.item_code} ${item.name} ${item.description || ''}`.toLowerCase())}" data-status="${item.is_active ? 'active' : 'inactive'}"><td><strong>${htmlEscape(item.item_code)}</strong></td><td>${htmlEscape(item.name)}</td><td>${htmlEscape(item.description || '—')}</td><td>${htmlEscape(item.unit)}</td><td><span class="pill ${item.is_active ? 'active' : 'planned'}">${item.is_active ? 'Activo' : 'Inactivo'}</span></td><td><button class="link-button" type="button" data-edit-purchase-item="${item.id}">Editar</button></td></tr>`).join('');
  const requestRows = requests.map(request => `<tr data-purchase-request-row data-search="${htmlEscape(`${request.request_code} ${request.item_summary || ''} ${request.supplier_name} ${request.description}`.toLowerCase())}" data-status="${request.status}" data-supplier="${request.supplier_id}"><td><strong>${htmlEscape(request.request_code)}</strong></td><td>${htmlEscape(request.item_summary || 'Sin items')}</td><td>${htmlEscape(request.supplier_name)}</td><td>${htmlEscape(request.description)}<small class="table-subtext">${htmlEscape(String(request.requested_on))} · Requerido: ${htmlEscape(String(request.required_by || '—'))}</small></td><td><span class="pill active">${statusLabels[request.status] || request.status}</span></td><td><button class="link-button" type="button" data-edit-purchase-request="${request.id}">Editar</button></td></tr>`).join('');
  const quotationRows = (quoteData.quotations || []).map(quotation => `<tr data-purchase-quotation-row data-search="${htmlEscape(`${quotation.quote_code} ${quotation.request_code} ${quotation.supplier_name}`.toLowerCase())}" data-status="${quotation.status}" data-supplier="${quotation.supplier_id}"><td><strong>${htmlEscape(quotation.quote_code)}</strong></td><td>${htmlEscape(quotation.request_code)}</td><td>${htmlEscape(quotation.supplier_name)}</td><td>${htmlEscape(String(quotation.quoted_on))}<small class="table-subtext">Válida hasta: ${htmlEscape(String(quotation.valid_until || '—'))}</small></td><td>${quotation.total_amount == null ? '—' : htmlEscape(Number(quotation.total_amount).toFixed(2))}</td><td><span class="pill active">${quoteStatusLabels[quotation.status] || quotation.status}</span></td><td><button class="link-button" type="button" data-edit-purchase-quotation="${quotation.id}">Editar</button></td></tr>`).join('');
  const requestOptions = requests.map(request => `<option value="${request.id}">${htmlEscape(request.request_code)} · ${htmlEscape(request.description)}</option>`).join('');
  const modal = `<div class="modal-backdrop" id="purchase-workspace-modal" hidden><section class="customer-modal purchase-request-modal" role="dialog" aria-modal="true"><div class="customer-modal-header"><div><p class="eyebrow">COMPRAS / ${title.toUpperCase()}</p><h3 id="purchase-workspace-form-title">Nuevo registro</h3><p class="muted">Mantén el catálogo y el flujo de abastecimiento relacionados.</p></div><button class="modal-close" id="purchase-workspace-cancel" type="button" aria-label="Cerrar">×</button></div><form id="purchase-workspace-form" class="customer-form"></form></section></div>`;
