  if (view === 'requests') content = `<section class="module-card"><div class="section-heading"><div><h3>Directorio de solicitudes</h3><p class="muted"><span id="purchase-result-count">${requests.length}</span> registradas.</p></div></div><div class="directory-filters"><label>Buscar<input id="purchase-filter-search" type="search" placeholder="Código, item, proveedor"></label><label>Proveedor<select id="purchase-filter-supplier"><option value="">Todos</option>${supplierOptions}</select></label><label>Estado<select id="purchase-filter-status"><option value="">Todos</option>${Object.entries(statusLabels).map(([key, label]) => `<option value="${key}">${label}</option>`).join('')}</select></label><button class="link-button filter-clear" id="purchase-filter-clear" type="button">Limpiar</button></div><div class="directory-table-wrap"><table class="directory-table purchase-request-table"><thead><tr><th>Solicitud</th><th>Items relacionados</th><th>Proveedor</th><th>Descripción y fechas</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${requestRows || '<tr><td colspan="6">No hay solicitudes registradas.</td></tr>'}</tbody></table></div></section>`;
  if (view === 'quotations') content = `<section class="module-card"><div class="section-heading"><div><h3>Directorio de cotizaciones</h3><p class="muted"><span id="purchase-result-count">${quoteData.quotations.length}</span> registradas.</p></div></div><div class="directory-filters"><label>Buscar<input id="purchase-filter-search" type="search" placeholder="Código, solicitud o proveedor"></label><label>Proveedor<select id="purchase-filter-supplier"><option value="">Todos</option>${quoteData.suppliers.map(supplier => `<option value="${supplier.id}">${htmlEscape(supplier.name)}</option>`).join('')}</select></label><label>Estado<select id="purchase-filter-status"><option value="">Todos</option>${Object.entries(quoteStatusLabels).map(([key, label]) => `<option value="${key}">${label}</option>`).join('')}</select></label><button class="link-button filter-clear" id="purchase-filter-clear" type="button">Limpiar</button></div><div class="directory-table-wrap"><table class="directory-table"><thead><tr><th>Cotización</th><th>Solicitud</th><th>Proveedor</th><th>Fechas</th><th>Total</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${quotationRows || '<tr><td colspan="7">No hay cotizaciones registradas.</td></tr>'}</tbody></table></div></section>`;
  $('#page-title').textContent = domainDefinitions.purchases.title;
  $('#workspace-content').innerHTML = `${domainNav(domainDefinitions.purchases, section)}<section class="hero"><div><p class="eyebrow">${eyebrow}</p><h2>${title}</h2><p>Gestiona items, solicitudes y cotizaciones en un solo flujo.</p></div></section>${ribbon}${content}${modal}`;
  const workspaceModal = $('#purchase-workspace-modal'); const form = $('#purchase-workspace-form'); let lineIndex = 0;
  const closeModal = () => { workspaceModal.hidden = true; document.body.classList.remove('modal-open'); };
  const addLine = line => { const row = document.createElement('div'); row.className = 'purchase-line-row'; row.dataset.line = String(lineIndex++); row.innerHTML = `<select name="line_item" required><option value="">Item *</option>${itemOptions}</select><input name="line_quantity" type="number" min="0.000001" step="0.000001" value="${line?.quantity || 1}" required><input name="line_unit" value="${htmlEscape(line?.unit || '')}" placeholder="Unidad" required><input name="line_presentation" value="${htmlEscape(line?.presentation || '')}" placeholder="Presentación / detalle"><button type="button" class="link-button remove-purchase-line">×</button>`; row.querySelector('[name=line_item]').value = line?.item_id || ''; row.querySelector('.remove-purchase-line').addEventListener('click', () => { if (document.querySelectorAll('.purchase-line-row').length > 1) row.remove(); }); $('#purchase-request-lines').append(row); };
  const openForm = (kind, record = null) => { let fields = ''; if (kind === 'items') fields = `<input type="hidden" name="item_id" value="${record?.id || ''}"><input type="hidden" name="item_type" value="${requestType}"><div class="customer-grid"><label>Código *<input name="item_code" required value="${htmlEscape(record?.item_code || '')}"></label><label>Nombre *<input name="name" required value="${htmlEscape(record?.name || '')}"></label><label>Unidad base *<input name="unit" required value="${htmlEscape(record?.unit || '')}"></label><label class="checkbox-field"><input name="is_active" type="checkbox" ${record?.is_active !== false ? 'checked' : ''}> Item activo</label></div><label>Descripción<textarea name="description">${htmlEscape(record?.description || '')}</textarea>`; if (kind === 'requests') fields = `<input type="hidden" name="request_id" value="${record?.id || ''}"><input type="hidden" name="request_type" value="${requestType}"><div class="customer-grid"><label>Código de solicitud *<input name="request_code" required value="${htmlEscape(record?.request_code || '')}"></label><label>Proveedor *<select name="supplier_id" required><option value="">Selecciona</option>${supplierOptions}</select></label><label>Estado<select name="status">${Object.entries(statusLabels).map(([key, label]) => `<option value="${key}">${label}</option>`).join('')}</select></label><label>Fecha de solicitud *<input name="requested_on" type="date" required value="${record?.requested_on || new Date().toISOString().slice(0,10)}"></label><label>Requerido para<input name="required_by" type="date" value="${record?.required_by || ''}"></label></div><label>Descripción *<textarea name="description" required>${htmlEscape(record?.description || '')}</textarea></label><div id="purchase-request-lines" class="purchase-lines-form"></div><button type="button" class="link-button" id="add-purchase-line">+ Añadir otro item</button><label>Observaciones<textarea name="observations">${htmlEscape(record?.observations || '')}</textarea>`; if (kind === 'quotations') fields = `<input type="hidden" name="quotation_id" value="${record?.id || ''}"><div class="customer-grid"><label>Solicitud *<select name="request_id" required><option value="">Selecciona una solicitud</option>${requestOptions}</select></label><label>Proveedor *<select name="supplier_id" required><option value="">Selecciona un proveedor</option>${supplierOptions}</select></label><label>Código de cotización *<input name="quote_code" required value="${htmlEscape(record?.quote_code || '')}"></label><label>Fecha *<input name="quoted_on" type="date" required value="${record?.quoted_on || new Date().toISOString().slice(0,10)}"></label><label>Válida hasta<input name="valid_until" type="date" value="${record?.valid_until || ''}"></label><label>Total<input name="total_amount" type="number" min="0" step="0.01" value="${record?.total_amount || ''}"></label><label>Estado<select name="status">${Object.entries(quoteStatusLabels).map(([key, label]) => `<option value="${key}">${label}</option>`).join('')}</select></label></div><label>Observaciones<textarea name="observations">${htmlEscape(record?.observations || '')}</textarea>`; form.innerHTML = `${fields}<div class="company-form-footer"><button class="primary" type="submit">Guardar</button><button class="link-button" type="button" id="purchase-form-cancel">Cancelar</button></div>`; $('#purchase-workspace-form-title').textContent = record ? `Editar ${kind === 'items' ? 'item' : kind === 'requests' ? 'solicitud' : 'cotización'}` : `Registrar ${kind === 'items' ? 'item' : kind === 'requests' ? 'solicitud' : 'cotización'}`; workspaceModal.hidden = false; document.body.classList.add('modal-open'); if (kind === 'requests') { $('#purchase-request-lines').innerHTML = ''; (record?.items || [{}]).forEach(addLine); $('#add-purchase-line').addEventListener('click', () => addLine({})); form.elements.supplier_id.value = record?.supplier_id || ''; form.elements.status.value = record?.status || 'draft'; } if (kind === 'quotations') { form.elements.request_id.value = record?.request_id || ''; form.elements.supplier_id.value = record?.supplier_id || ''; form.elements.status.value = record?.status || 'received'; } $('#purchase-form-cancel').addEventListener('click', closeModal); };
  $('#purchase-workspace-cancel').addEventListener('click', closeModal); workspaceModal.addEventListener('click', event => { if (event.target === workspaceModal) closeModal(); });
  form.addEventListener('submit', async event => { event.preventDefault(); const values = Object.fromEntries(new FormData(form)); let payload; let endpoint; let method; if (view === 'items') { payload = { item_type: requestType, item_code: values.item_code, name: values.name, description: values.description || null, unit: values.unit, is_active: form.elements.is_active.checked }; endpoint = values.item_id ? `/purchases/items/${values.item_id}` : '/purchases/items'; method = values.item_id ? 'PATCH' : 'POST'; } else if (view === 'requests') { const itemsPayload = [...form.querySelectorAll('.purchase-line-row')].map(row => ({ item_id: Number(row.querySelector('[name=line_item]').value), quantity: Number(row.querySelector('[name=line_quantity]').value), unit: row.querySelector('[name=line_unit]').value, presentation: row.querySelector('[name=line_presentation]').value || null })); payload = { request_type: requestType, request_code: values.request_code, items: itemsPayload, supplier_id: Number(values.supplier_id), description: values.description, requested_on: values.requested_on, required_by: values.required_by || null, status: values.status, observations: values.observations || null }; endpoint = values.request_id ? `/purchases/requests/${values.request_id}` : '/purchases/requests'; method = values.request_id ? 'PATCH' : 'POST'; } else { payload = { request_id: Number(values.request_id), quote_code: values.quote_code, supplier_id: Number(values.supplier_id), quoted_on: values.quoted_on, valid_until: values.valid_until || null, status: values.status, total_amount: values.total_amount ? Number(values.total_amount) : null, observations: values.observations || null }; endpoint = values.quotation_id ? `/purchases/quotations/${values.quotation_id}` : '/purchases/quotations'; method = values.quotation_id ? 'PATCH' : 'POST'; } try { await api(endpoint, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); closeModal(); toast('Registro guardado'); loadPurchaseRequests(section, view); } catch (error) { toast(error.message); } });
  document.querySelectorAll('[data-purchase-view]').forEach(button => button.addEventListener('click', () => loadPurchaseRequests(section, button.dataset.purchaseView))); $('#purchase-new-items')?.addEventListener('click', () => openForm('items')); $('#purchase-new-requests')?.addEventListener('click', () => openForm('requests')); $('#purchase-new-quotations')?.addEventListener('click', () => openForm('quotations'));
  document.querySelectorAll('[data-edit-purchase-item]').forEach(button => button.addEventListener('click', () => openForm('items', items.find(item => String(item.id) === button.dataset.editPurchaseItem)))); document.querySelectorAll('[data-edit-purchase-request]').forEach(button => button.addEventListener('click', () => openForm('requests', requests.find(item => String(item.id) === button.dataset.editPurchaseRequest)))); document.querySelectorAll('[data-edit-purchase-quotation]').forEach(button => button.addEventListener('click', () => openForm('quotations', quoteData.quotations.find(item => String(item.id) === button.dataset.editPurchaseQuotation))));
