  const filter = () => { const search = $('#purchase-order-filter-search').value.trim().toLowerCase(); const status = $('#purchase-order-filter-status').value; let visible = 0; document.querySelectorAll('[data-purchase-order-row]').forEach(row => { const matches = (!search || row.dataset.search.includes(search)) && (!status || row.dataset.status === status); row.hidden = !matches; if (matches) visible += 1; }); $('#purchase-order-result-count').textContent = visible; }; $('#purchase-order-filter-search').addEventListener('input', filter); $('#purchase-order-filter-status').addEventListener('input', filter); $('#purchase-order-filter-clear').addEventListener('click', () => { $('#purchase-order-filter-search').value = ''; $('#purchase-order-filter-status').value = ''; filter(); }); document.querySelectorAll('[data-domain-section]').forEach(button => button.addEventListener('click', () => loadDomain('purchases', button.dataset.domainSection)));
