  const projectOptions = data.projects.map(project => `<option value="${project.id}">${htmlEscape(project.project_code)} · ${htmlEscape(project.name)}</option>`).join(''); const workerOptions = data.workers.map(worker => `<option value="${worker.id}">${htmlEscape(worker.worker_code)} · ${htmlEscape(worker.full_name)}</option>`).join('');
